-- Runtime error messages: not just the words but the hint about *which*
-- value went wrong.  'ldebug.c' works that hint out from the bytecode
-- that raised the error -- is the operand a local, an upvalue, a global,
-- a field, a constant? -- and the wording changes with the answer.
local function show(...)
  local n = select('#', ...)
  local t = {}
  for i = 1, n do
    local v = (select(i, ...))
    if type(v) == "string" then t[i] = string.format("%q", v)
    elseif v == nil then t[i] = "nil"
    elseif type(v) == "number" then t[i] = string.format("%.17g", v)
    else
      local ok, s = pcall(tostring, v)
      t[i] = ok and s or ("<" .. type(v) .. ">")
    end
  end
  return table.concat(t, "|")
end
local function rec(f, ...) return show(pcall(f, ...)) end
-- strip the "file:line: " prefix so the wording is what is compared
local function rec2(f, ...)
  local ok, e = pcall(f, ...)
  if ok then return "ok|" .. show(...) end
  return "err|" .. (tostring(e):gsub("^[^:]*:%d+: ", ""))
end

print("== arithmetic: hint by kind of value ==")
local lv = nil
print(rec2(function() return lv + 1 end))      -- upvalue 'lv'
print(rec2(function() local z = nil return z + 1 end))
print(rec2(function() local z = nil return 1 + z end))
print(rec2(function() local z = nil return z - 1 end))
print(rec2(function() local z = nil return z * 2 end))
print(rec2(function() local z = nil return z / 2 end))
print(rec2(function() local z = nil return z // 2 end))
print(rec2(function() local z = nil return z % 2 end))
print(rec2(function() local z = nil return z ^ 2 end))
print(rec2(function() local z = nil return -z end))
print(rec2(function() local z = nil return ~z end))
print(rec2(function() local z = nil return z & 1 end))
print(rec2(function() local z = nil return z | 1 end))
print(rec2(function() local z = nil return z ~ 1 end))
print(rec2(function() local z = nil return z << 1 end))
print(rec2(function() local z = nil return z >> 1 end))

