print("== 'for' and the generic 'for' ==")
print(rec2(function() for i = "a", 10 do end end))
print(rec2(function() for i = 1, "a" do end end))
print(rec2(function() for i = 1, 10, "a" do end end))
print(rec2(function() for i = 1, 10, 0 do end end))
