print("== the hint when the value comes from a call or an index ==")
print(rec2(function() return (function() end)() + 1 end))
print(rec2(function() local t = {x = nil} return t.x + 1 end))
print(rec2(function() local t = {x = nil} return t[1] + 1 end))
