print(rec2(function() local a, b = 1, nil return a + b end))
print(rec2(function() return select(2, 1) + 1 end))
print(rec2(function() return (nil) + 1 end))
print(rec2(function() local t = setmetatable({}, {__index = function() return nil end}) return t.x + 1 end))

print("== error levels ==")
print(rec2(function() error("msg") end))
print(rec2(function() error("msg", 0) end))
print(rec2(function() error("msg", 1) end))
print(rec2(function() error("msg", 2) end))
print(rec2(function() error("msg", 3) end))
