print(rec2(xpcall))
print(rec2(function() return xpcall(function() error("z") end, function() error("in handler") end) end))
print(rec2(function() return select(2, pcall(error, "x")) end))
print(rec2(select, 0))
print(rec2(select, -1))
print(rec2(select, 1, 2))
print(rec2(select, "#"))
